.app{display:block}.sidebar{position:fixed;z-index:8;left:0;top:0;bottom:0;width:246px;background:#fff;border-right:1px solid #edf0f5;padding:25px 17px;display:flex;flex-direction:column;color:#16223b}.sidebar .brand{display:flex;align-items:center;gap:11px;padding:0 10px 25px;text-decoration:none;color:#16223b;font:800 16px Manrope}.brand-mark{width:38px;height:38px;border-radius:13px;background:linear-gradient(145deg,#6786ff,#425bd8);display:grid;place-items:center;color:#fff;box-shadow:0 7px 16px #536fe33b}.brand-mark svg{width:21px;height:21px}.sidebar .brand small,.workspace small,.side-profile small{display:block;font:500 10px 'DM Sans';color:#98a2b4;letter-spacing:.4px;margin-top:3px}.workspace{margin:0 7px 25px;padding:11px;border:1px solid #edf0f5;border-radius:13px;display:flex;align-items:center;gap:10px}.workspace b,.side-profile b{font-size:11px;display:block}.seal{width:31px;height:31px;border-radius:10px;background:#fff3df;color:#bd7812;display:grid;place-items:center;font-size:12px;font-weight:700}.nav-label{font-size:10px;font-weight:700;color:#a1aabc;letter-spacing:1px;padding:0 12px;margin:5px 0 8px}.nav-label-spaced{margin-top:20px}.side-nav{display:grid;gap:4px}.side-nav a{color:#77849b;text-decoration:none;padding:11px 12px;border-radius:11px;font-weight:600;display:flex;align-items:center;gap:12px;font-size:13px}.side-nav a svg{width:18px;height:18px;flex:none;stroke:currentColor}.side-nav a:hover{background:#f7f8fc}.side-nav a.active{background:#eef1ff;color:#4668e8}.side-profile{margin-top:auto;display:flex;align-items:center;gap:10px;padding:13px 8px 0;border-top:1px solid #edf0f5}.profile-avatar{width:35px;height:35px;border-radius:12px;background:#dce5ff;color:#425ed4;display:grid;place-items:center;font-weight:700}.mobile-toggle{display:none}.topbar .brand,.top .brand{display:none}body{padding-left:246px}.main,body>.shell{min-width:0}.back{display:none!important}
@media(max-width:760px){body{padding-left:0}.sidebar{left:-260px;transition:left .25s;box-shadow:12px 0 30px #14213b17}.sidebar.open{left:0}.mobile-toggle{display:inline-grid;place-items:center;border:1px solid #edf0f5;background:white;color:#52617b;border-radius:10px;width:36px;height:36px;cursor:pointer}.topbar .page-title{margin-right:auto}}
